package session

import (
	"context"
	"encoding/json"

	"github.com/humzakhan/capsule-memory/internal/memory"
	"github.com/humzakhan/capsule-memory/internal/ops"
	"github.com/humzakhan/capsule-memory/internal/records"
)
func(m *Module) Search(ctx context.Context,g Grant,query string,limit int)(SearchResult,error){result:=SearchResult{Results:[]SearchHit{}};if !g.Has(ops.CapSessionRead){return result,ops.ErrForbidden};if limit<=0||limit>100{limit=20};e:=m.svc.Read(ctx,func(q memory.Queryer)error{for _,scope:=range g.Scopes{rows,e:=q.QueryContext(ctx,"SELECT CASE WHEN COALESCE(s.view_of,'')='' THEN f.session ELSE s.view_of END,f.record,f.revision,snippet(session_search,5,'','', ' … ',24) FROM session_search f JOIN sessions s ON s.session=f.session WHERE session_search MATCH ? AND f.scope=? AND f.kind='session_chunk' AND s.deleted=0 AND NOT EXISTS(SELECT 1 FROM stale WHERE record=f.record OR record=f.session) ORDER BY rank LIMIT ?",query,scope,limit);if e!=nil{return memory.ErrInvalid};var hits []SearchHit;for rows.Next(){var h SearchHit;if rows.Scan(&h.Session,&h.Chunk,&h.Revision,&h.Snippet)!=nil{rows.Close();return memory.ErrStorage};h.Untrusted=true;hits=append(hits,h)};rows.Close();for _,h:=range hits{v,e:=memory.IsVisible(ctx,q,h.Chunk);if e!=nil{return e};if v&&len(result.Results)<limit{result.Results=append(result.Results,h)}}};return nil});result.Coverage,_=m.coverage(ctx,g.Scopes);return result,e}
func(m *Module) Events(ctx context.Context,q memory.Queryer,session,branch string,fromSeq int64,maxBytes int)([]records.SessionChunk,error){if maxBytes<=0||maxBytes>4<<20{maxBytes=4<<20};var deleted int;if e:=q.QueryRowContext(ctx,"SELECT deleted FROM sessions WHERE session=?",session).Scan(&deleted);e!=nil||deleted!=0{return nil,memory.ErrInvalid};visible,e:=memory.IsVisible(ctx,q,session);if e!=nil||!visible{return nil,memory.ErrInvalid};rows,e:=q.QueryContext(ctx,"SELECT r.body,c.record FROM chunks c JOIN revisions r ON r.revision=c.revision WHERE c.session IN(SELECT session FROM sessions WHERE session=? OR view_of=?) AND c.branch=? AND c.seq>=? ORDER BY c.seq,c.record",session,session,branch,fromSeq);if e!=nil{return nil,e};type row struct{b []byte;id string};var candidates []row;size:=0;sequences:=map[int64]bool{};for rows.Next(){var r row;if rows.Scan(&r.b,&r.id)!=nil{rows.Close();return nil,memory.ErrStorage};var revision memory.Revision;var chunk records.SessionChunk;if json.Unmarshal(r.b,&revision)!=nil||json.Unmarshal(revision.Body,&chunk)!=nil{rows.Close();return nil,memory.ErrStorage};if sequences[chunk.Seq]{rows.Close();return nil,memory.ErrHeadsChanged};if size+len(r.b)>maxBytes{if len(candidates)==0{rows.Close();return nil,memory.ErrInvalid};if len(candidates)>0{var next memory.Revision;var previous records.SessionChunk;if json.Unmarshal(candidates[len(candidates)-1].b,&next)!=nil||json.Unmarshal(next.Body,&previous)!=nil{rows.Close();return nil,memory.ErrStorage};if previous.Seq==chunk.Seq{rows.Close();return nil,memory.ErrHeadsChanged}};break};sequences[chunk.Seq]=true;size+=len(r.b);candidates=append(candidates,r)};rows.Close();var out []records.SessionChunk;for _,r:=range candidates{v,e:=memory.IsVisible(ctx,q,r.id);if e!=nil{return nil,e};if !v{continue};var rev memory.Revision;var c records.SessionChunk;if json.Unmarshal(r.b,&rev)!=nil||json.Unmarshal(rev.Body,&c)!=nil{return nil,memory.ErrStorage};out=append(out,c)};return out,nil}
func(m *Module) ReadSession(ctx context.Context,g Grant,session,branch string,fromSeq int64,maxBytes int)(ReadResult,error){result:=ReadResult{};if !g.Has(ops.CapSessionRead){return result,ops.ErrForbidden};if branch==""{branch="main"};scope:="";e:=m.svc.Read(ctx,func(q memory.Queryer)error{if q.QueryRowContext(ctx,"SELECT scope,CASE WHEN COALESCE(view_of,'')='' THEN session ELSE view_of END FROM sessions WHERE session=?",session).Scan(&scope,&session)!=nil||!g.AllowsScope(scope){return ops.ErrForbidden};rows,e:=q.QueryContext(ctx,"SELECT DISTINCT branch FROM chunks WHERE session IN(SELECT session FROM sessions WHERE session=? OR view_of=?) ORDER BY branch",session,session);if e!=nil{return e};for rows.Next(){var b string;if rows.Scan(&b)!=nil{rows.Close();return memory.ErrStorage};result.Branches=append(result.Branches,b)};e=rows.Err();rows.Close();if e!=nil{return e};if branch=="main"{found:=false;for _,b:=range result.Branches{found=found||b==branch};if !found&&len(result.Branches)>0{branch=result.Branches[0]}};result.Branch=branch;result.Chunks,e=m.Events(ctx,q,session,branch,fromSeq,maxBytes);return e});if e!=nil{return result,e};result.Next=fromSeq;contiguous:=true;for _,c:=range result.Chunks{if c.Seq!=result.Next{contiguous=false};result.Next=c.Seq+1};result.Coverage,e=m.coverage(ctx,[]string{scope});result.Complete=contiguous&&result.Coverage.Complete;_ = m.svc.Read(ctx,func(q memory.Queryer)error{var high int64;if e:=q.QueryRowContext(ctx,"SELECT COALESCE(max(seq),-1) FROM chunks WHERE session IN(SELECT session FROM sessions WHERE session=? OR view_of=?) AND branch=?",session,session,branch).Scan(&high);e!=nil{return e};if result.Next<=high{result.Complete=false};return nil});return result,e}
func(m *Module) coverage(ctx context.Context,scopes []string)(Coverage,error){c:=Coverage{Complete:true};e:=m.svc.Read(ctx,func(q memory.Queryer)error{var pending int;if e:=q.QueryRowContext(ctx,"SELECT (SELECT count(*) FROM checkpoints WHERE caught_up=0 OR state IN ('gap','quarantined'))+(SELECT count(*) FROM sources WHERE enabled=1 AND state IN ('paused','blocked','quarantined','unavailable'))").Scan(&pending);e!=nil{return e};if pending>0{c.Complete=false};for _,scope:=range scopes{var count int;if e:=q.QueryRowContext(ctx,"SELECT count(*) FROM chunks c JOIN sessions s ON s.session=c.session WHERE s.scope=? AND s.deleted=0",scope).Scan(&count);e!=nil{return e};c.AvailableChunks+=count;var indexed int;if e:=q.QueryRowContext(ctx,"SELECT count(*) FROM session_search WHERE scope=? AND kind='session_chunk'",scope).Scan(&indexed);e!=nil{return e};c.IndexedChunks+=indexed;status,e:=m.svc.ScopeStatusQuery(ctx,q,scope);if e!=nil{return e};c.SourceHeads=append(c.SourceHeads,status.Coverage.Head);if !status.Coverage.Complete||status.Blocked!=""||indexed!=count{c.Complete=false};var stale int;if e=q.QueryRowContext(ctx,"SELECT count(*) FROM stale x JOIN sessions s ON s.session=x.record WHERE s.scope=?",scope).Scan(&stale);e!=nil{return e};c.StaleDependencies+=stale;rows,e:=q.QueryContext(ctx,"SELECT session FROM sessions WHERE scope=? AND deleted=0 ORDER BY session LIMIT 100001",scope);if e!=nil{return e};var manifests []string;for rows.Next(){var id string;if rows.Scan(&id)!=nil{rows.Close();return memory.ErrStorage};manifests=append(manifests,id)};e=rows.Err();rows.Close();if e!=nil{return e};if len(manifests)>100000{return memory.ErrStaleOverflow};for _,id:=range manifests{heads,deleted,e:=m.svc.Heads(ctx,q,scope,id);if e!=nil{return e};if deleted||len(heads)!=1{c.Complete=false;continue};var manifest records.SessionManifest;if json.Unmarshal(heads[0].Body,&manifest)!=nil{return memory.ErrStorage};if len(manifest.Gaps)>0{c.Complete=false;c.Gaps=append(c.Gaps,manifest.Gaps...)};root:=id;for n:=0;manifest.Continues!="";n++{if n>=1024{return memory.ErrInvalid};root=manifest.Continues;prior,deleted,e:=m.svc.Heads(ctx,q,scope,root);if e!=nil{return e};if deleted||len(prior)!=1{c.Complete=false;break};var previous records.SessionManifest;if json.Unmarshal(prior[0].Body,&previous)!=nil{return memory.ErrStorage};manifest.Continues=previous.Continues};for branch,high:=range manifest.ChunkHigh{var got int;if e=q.QueryRowContext(ctx,"SELECT count(DISTINCT seq) FROM chunks WHERE session=? AND branch=?",root,branch).Scan(&got);e!=nil{return e};if int64(got)<high+1{c.Complete=false}}}};rows,e:=q.QueryContext(ctx,"SELECT reason,sum(count) FROM source_gaps GROUP BY reason ORDER BY reason");if e!=nil{return e};for rows.Next(){var gap records.Gap;if rows.Scan(&gap.Reason,&gap.Count)!=nil{rows.Close();return memory.ErrStorage};c.Gaps=append(c.Gaps,gap);c.Complete=false};e=rows.Err();rows.Close();return e});return c,e}
